import{_ as n,a0 as a,w as l,s as i,ao as S,I as p,x as e,a1 as r,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"ESI 集团同 ENSAM 合作，开源其 Inpsector 软件 | LCTT x X-CMD","titleTemplate":false,"description":"ESI 集团同 ENSAM 合作，开源其 Inpsector 软件 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"ESI 集团同 ENSAM 合作，开源其 Inpsector 软件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"ESI 集团同 ENSAM 合作，开源其 Inpsector 软件 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220504 ESI Group Collaborates With ENSAM, Open Sources Its “Inspector” Software","title":"ESI 集团同 ENSAM 合作，开源其 Inpsector 软件","tag":"202205","desc":""},"relativePath":"202205/20220504 ESI Group Collaborates With ENSAM, Open Sources Its “Inspector” Software.md","filePath":"[post].md"}'),u={name:"202205/20220504 ESI Group Collaborates With ENSAM, Open Sources Its “Inspector” Software.md"};function I(f,t,E,m,d,w){const o=a("Link");return l(),i("div",null,[t[15]||(t[15]=S('<h1 id="esi-集团同-ensam-合作-开源其-inpsector-软件" tabindex="-1">ESI 集团同 ENSAM 合作，开源其 Inpsector 软件 <a class="header-anchor" href="#esi-集团同-ensam-合作-开源其-inpsector-软件" aria-label="Permalink to “ESI 集团同 ENSAM 合作，开源其 Inpsector 软件”">​</a></h1><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/05/software-696x371.jpg" alt="software"></p><p>Inspector 是一个可视化的交互式数据探索软件，能够对海量数据进行分析并提取相关信息，可用于预测性维修、网络安全、控制、机器学习算法分析等。</p><p>通过让更多的人使用 Inspector 软件，让他们能够合作开发可靠灵活的方案，以解决社区的技术问题和特殊需求，ESI 集团增加了对工业界和学术界的贡献。</p><p>作为 ESI 集团和 ENSAM 之间持续赞助合作和共创伙伴关系的一部分，将由 ENSAM（<ruby>巴黎高科国立高等工程技术大学<rt>Ecole Nationale Supérieure d’Arts et Métiers</rt></ruby>）领导 Inspector 的增长和扩展。通过共同参与建设由新加坡国家科学研究中（CNRS）协调的 Descartes 计划、CREATE-ID 国际研究讲座以及 ESI – ENSAM 虚拟工程实验室，双方加强了合作。</p><p>这种开源方式有许多好处。首先，社区能够以最有效的方式使用该软件，科学界能够从根据用户需求定制的新功能以及安全方面的改进中受益。其次，ESI 集团希望提供一个从软件中获利机会，包括汽车及航空在内的各种行业的客户已经证明了这一软件的可靠性。由于许多利益相关者的参与，Inspector 将持续发展以应对社区需求。</p><p>ESI 集团打算将其数据分析软件开源发布，得到了一些行业领导者和 Inspector 用户的兴趣和支持，例如 CNS 就是其中一例。</p><p>CNS 的总经理 Stephane Perrin 表示：“ESI 集团这一决定证明了集团的先进技术对创新和科学生态系统的贡献。CNS 作为一家网络与安全的专业公司，我们用行动支持 Inspector 的未来。除了将 Inspector 集成到我们的持续网络审计软件套件中外，不久后我们还将通过我们创新解决方案的业务部门为该软件提供支持。”</p><hr>',9)),p("p",null,[t[1]||(t[1]=e("via: ",-1)),r(o,{href:"https://www.opensourceforu.com/2022/05/esi-group-collaborates-with-ensam-open-sources-its-inspector-software/"},{default:s(()=>[...t[0]||(t[0]=[e("https://www.opensourceforu.com/2022/05/esi-group-collaborates-with-ensam-open-sources-its-inspector-software/",-1)])]),_:1})]),p("p",null,[t[6]||(t[6]=e("作者：",-1)),r(o,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:s(()=>[...t[2]||(t[2]=[e("Laveesh Kocher",-1)])]),_:1}),t[7]||(t[7]=e(" 选题：",-1)),r(o,{href:"https://github.com/lkxed"},{default:s(()=>[...t[3]||(t[3]=[e("lkxed",-1)])]),_:1}),t[8]||(t[8]=e(" 译者：",-1)),r(o,{href:"https://github.com/Veryzzj"},{default:s(()=>[...t[4]||(t[4]=[e("Veryzzj",-1)])]),_:1}),t[9]||(t[9]=e(" 校对：",-1)),r(o,{href:"https://github.com/wxy"},{default:s(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),p("p",null,[t[12]||(t[12]=e("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原创编译，",-1)),r(o,{href:"https://linux.cn/"},{default:s(()=>[...t[11]||(t[11]=[e("Linux中国",-1)])]),_:1}),t[14]||(t[14]=e(" 荣誉推出",-1))])])}const A=n(u,[["render",I]]);export{T as __pageData,A as default};
